package com.tcrrry.diary;
import org.junit.Test;
import static org.junit.Assert.*;
import java.util.*;
public class ListeningClockTest {
    private ListeningClock.Sample s(String id,long elapsed,long pos,boolean playing){return new ListeningClock.Sample(id,id,"artist","album",1000000+elapsed,elapsed,pos,240000,playing,1);}
    @Test public void pauseAndResumeExcludePause(){List<ListeningClock.Chunk> out=new ArrayList<>();ListeningClock c=new ListeningClock(out::add);c.accept(s("a",0,0,true),"start");c.accept(s("a",20000,20000,false),"pause");c.accept(s("a",40000,20000,true),"resume");c.accept(s("a",50000,30000,false),"pause");assertEquals(30000,out.stream().mapToLong(v->v.millis).sum());assertEquals(out.get(0).visit,out.get(1).visit);}
    @Test public void seekDoesNotCreditSeekDistance(){List<ListeningClock.Chunk> out=new ArrayList<>();ListeningClock c=new ListeningClock(out::add);c.accept(s("a",0,0,true),"start");c.accept(s("a",1000,220000,true),"seek");c.accept(s("a",2000,10000,true),"seek");assertEquals(2000,out.stream().mapToLong(v->v.millis).sum());}
    @Test public void songChangeCreditsOldSong(){List<ListeningClock.Chunk> out=new ArrayList<>();ListeningClock c=new ListeningClock(out::add);c.accept(s("a",0,0,true),"start");c.accept(s("b",10000,0,true),"track");c.accept(s("b",20000,10000,false),"pause");assertEquals("a",out.get(0).song.id);assertEquals("b",out.get(1).song.id);assertNotEquals(out.get(0).visit,out.get(1).visit);}
    @Test public void crashGapNotInvented(){List<ListeningClock.Chunk> out=new ArrayList<>();ListeningClock c=new ListeningClock(out::add);c.accept(s("a",0,0,true),"start");c.accept(s("a",3600000,20000,true),"tick");assertTrue(out.isEmpty());}
    @Test public void stationaryControllerNotCounted(){List<ListeningClock.Chunk> out=new ArrayList<>();ListeningClock c=new ListeningClock(out::add);c.accept(s("a",0,10000,true),"start");c.accept(s("a",15000,10000,true),"tick");assertTrue(out.isEmpty());}
    @Test public void durationCapsTail(){List<ListeningClock.Chunk> out=new ArrayList<>();ListeningClock c=new ListeningClock(out::add);c.accept(s("a",0,239000,true),"start");c.accept(s("b",15000,0,true),"track");assertEquals(1000,out.get(0).millis);}
    @Test public void naturalRepeatCreatesAnotherVisit(){List<ListeningClock.Chunk> out=new ArrayList<>();ListeningClock c=new ListeningClock(out::add);c.accept(s("a",0,235000,true),"start");c.accept(s("a",5000,0,true),"tick");c.accept(s("a",10000,5000,true),"tick");assertNotEquals(out.get(0).visit,out.get(1).visit);assertEquals(10000,out.stream().mapToLong(v->v.millis).sum());}
    @Test public void resetNeverBridgesMissingTime(){List<ListeningClock.Chunk> out=new ArrayList<>();ListeningClock c=new ListeningClock(out::add);c.accept(s("a",0,0,true),"start");c.reset();c.accept(s("a",10000,10000,true),"start");assertTrue(out.isEmpty());}
    @Test public void backwardWallClockDoesNotChangeDuration(){List<ListeningClock.Chunk> out=new ArrayList<>();ListeningClock c=new ListeningClock(out::add);c.accept(s("a",10000,0,true),"start");c.accept(new ListeningClock.Sample("a","a","artist","album",100,20000,10000,240000,false,1),"pause");assertEquals(10000,out.get(0).millis);}
    @Test public void playbackSpeedMeasuresRealMinutes(){List<ListeningClock.Chunk> out=new ArrayList<>();ListeningClock c=new ListeningClock(out::add);c.accept(new ListeningClock.Sample("a","a","artist","album",0,0,0,240000,true,2),"start");c.accept(s("a",10000,20000,false),"pause");assertEquals(10000,out.get(0).millis);}
    @Test public void repeatBetweenCheckpointsPreservesWholeInterval(){List<ListeningClock.Chunk> out=new ArrayList<>();ListeningClock c=new ListeningClock(out::add);c.accept(s("a",0,230000,true),"start");c.accept(s("a",15000,5000,true),"tick");assertEquals(15000,out.stream().mapToLong(v->v.millis).sum());assertEquals(2,out.size());assertNotEquals(out.get(0).visit,out.get(1).visit);}
}
